"use strict";

function retryLite(fn, opts) {
  const retries = opts.retries === undefined ? 3 : opts.retries;
  return new Promise((resolve, reject) => {
    let attempt = 0;
    let bailed = false;
    const bail = (err) => {
      bailed = true;
      reject(err);
    };
    const onError = (err) => {
      if (bailed) return;
      if (attempt > retries) {
        reject(err);
        return;
      }
      if (opts.onRetry) opts.onRetry(err);
      runAttempt();
    };
    const runAttempt = () => {
      attempt++;
      let val;
      try {
        val = fn(bail, attempt);
      } catch (err) {
        onError(err);
        return;
      }
      Promise.resolve(val).then(resolve).catch(onError);
    };
    runAttempt();
  });
}

module.exports = retryLite;
